SET NAMES utf8mb4;
SET time_zone = '-06:00';

-- ================================================================
-- 1. TABLA RESCATES
--    Seguimiento de rescates y mantenimientos Bisonte SLP / Consigna Kenworth
-- ================================================================
CREATE TABLE IF NOT EXISTS `rescates` (
  `id`                  INT AUTO_INCREMENT PRIMARY KEY                                  COMMENT 'Identificador unico autoincremental',
  `fecha`               DATE NOT NULL                                                   COMMENT 'Fecha en que se realizo el rescate o mantenimiento',
  `folio_interno`       VARCHAR(30)                                                     COMMENT 'Folio interno SITIC - enlace con ventas_reporte.id_docto_cargo',
  `tipo`                ENUM('RESCATE','MTTO') NOT NULL DEFAULT 'RESCATE'               COMMENT 'RESCATE: unidad varada en carretera | MTTO: mantenimiento programado',
  `destino`             VARCHAR(120)                                                    COMMENT 'Ciudad o lugar al que se envio el material',
  `item`                VARCHAR(60)                                                     COMMENT 'Numero de parte o SKU del articulo enviado',
  `descripcion`         TEXT                                                            COMMENT 'Descripcion completa del articulo segun catalogo',
  `cantidad_entregada`  DECIMAL(10,4) DEFAULT 0                                        COMMENT 'Piezas enviadas al destino',
  `cantidad_devuelta`   DECIMAL(10,4) DEFAULT 0                                        COMMENT 'Piezas devueltas al almacen',
  `cantidad_usada`      DECIMAL(10,4) DEFAULT 0                                        COMMENT 'Piezas efectivamente utilizadas en la reparacion',
  `cantidad_pendiente`  DECIMAL(10,4) DEFAULT 0                                        COMMENT 'Piezas pendientes de devolucion o cobro',
  `status_bisonte`      VARCHAR(150)                                                    COMMENT 'Estado segun Bisonte: VALE ENTREGADO POR BISONTE | SE REGRESA MATERIAL | PENDIENTE',
  `status_kw`           VARCHAR(150)                                                    COMMENT 'Estado KW: Devuelta | Facturada | Impresa | Parcialmente Devuelta | Parcialmente Devuelta y Parcialmente Facturada | Parcialmente Facturada | Sin Imprimir',
  `tecnico`             VARCHAR(100)                                                    COMMENT 'Nombre del tecnico responsable del rescate o mtto',
  `unidad`              VARCHAR(50)                                                     COMMENT 'Numero economico de la unidad vehicular atendida (ej. T-691)',
  `bisonte`             VARCHAR(100)                                                    COMMENT 'Nombre del representante Bisonte responsable',
  `kw`                  VARCHAR(100)                                                    COMMENT 'Nombre del vendedor KW responsable (ej. MARIO RICO, YONA COBOS)',
  `vales`               VARCHAR(200)                                                    COMMENT 'Numero(s) de vale(s) Bisonte, separados por guion si son varios',
  `observaciones`       TEXT                                                            COMMENT 'Notas adicionales: cotizaciones, facturas, pagos, devoluciones',
  `created_at`          TIMESTAMP DEFAULT CURRENT_TIMESTAMP                            COMMENT 'Fecha de creacion del registro en el sistema',
  `updated_at`          TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Fecha de ultima modificacion del registro',
  INDEX `idx_folio`     (`folio_interno`),
  INDEX `idx_fecha`     (`fecha`),
  INDEX `idx_tipo`      (`tipo`),
  INDEX `idx_status_kw` (`status_kw`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Seguimiento de rescates y mantenimientos - Bisonte SLP / Consigna Kenworth';

-- ================================================================
-- 2. TABLA VENTAS_REPORTE
--    Reporte de ventas exportado del sistema SITIC (salidas en vale)
-- ================================================================
CREATE TABLE IF NOT EXISTS `ventas_reporte` (
  `id`                    INT AUTO_INCREMENT PRIMARY KEY        COMMENT 'Identificador unico autoincremental',
  `numero_articulo`       VARCHAR(60)                           COMMENT 'SKU o numero de parte del articulo',
  `cantidad_surtida`      DECIMAL(10,4) DEFAULT 0              COMMENT 'Piezas efectivamente surtidas al cliente',
  `cantidad_por_facturar` DECIMAL(10,4) DEFAULT 0              COMMENT 'Piezas pendientes de facturar',
  `id_docto_cargo`        BIGINT                                COMMENT 'Folio del vale de salida en SITIC - enlace con rescates.folio_interno',
  `folio_factura`         BIGINT                                COMMENT 'Numero de folio de la factura generada, NULL si no facturado',
  `serie_factura`         VARCHAR(60)                           COMMENT 'Serie de la factura (ej. ARLF)',
  `tipo_documento`        VARCHAR(100)                          COMMENT 'Tipo de movimiento en SITIC (ej. Salidas en Vale)',
  `estado_venta`          VARCHAR(120)                          COMMENT 'Estado: Devuelta | Facturada | Impresa | Parcialmente Devuelta | Parcialmente Devuelta y Parcialmente Facturada | Parcialmente Facturada | Sin Imprimir',
  `fecha`                 DATETIME                              COMMENT 'Fecha y hora del registro en SITIC',
  `descripcion`           TEXT                                  COMMENT 'Descripcion completa del articulo segun catalogo SITIC',
  `fecha_vencimiento`     DATETIME                              COMMENT 'Fecha limite de pago o devolucion del vale',
  `usuario_alta`          VARCHAR(100)                          COMMENT 'Usuario SITIC que genero el registro (ej. CONSIGNA SAN LUIS POTOSI)',
  `observaciones`         TEXT                                  COMMENT 'Notas libres: cotizacion origen, vendedor, OC cliente',
  `oc_cliente`            VARCHAR(100)                          COMMENT 'Numero de orden de compra del cliente Bisonte',
  `no_docto_venta`        INT                                   COMMENT 'Numero de documento de venta interno KW (consecutivo)',
  `created_at`            TIMESTAMP DEFAULT CURRENT_TIMESTAMP  COMMENT 'Fecha de insercion en esta base de datos',
  INDEX `idx_numero_articulo` (`numero_articulo`),
  INDEX `idx_id_docto`        (`id_docto_cargo`),
  INDEX `idx_estado`          (`estado_venta`),
  INDEX `idx_fecha_v`         (`fecha`),
  INDEX `idx_usuario`         (`usuario_alta`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Reporte de ventas/salidas en vale de SITIC - Consigna Kenworth Bisonte SLP';
-- ================================================================
-- 3. INSERT DATOS RESCATES (95 registros)
-- ================================================================
;

